def _line(cells):
    return "| " + " | ".join(cells) + " |"


def to_markdown(rows):
    """Render rows (first row is the header) as a GitHub markdown table."""
    if not rows:
        raise ValueError("no rows")
    header = rows[0]
    if not header:
        raise ValueError("header has no cells")
    width = len(header)
    lines = []
    for i, row in enumerate(rows):
        if len(row) != width:
            raise ValueError(f"row {i} has {len(row)} cells, expected {width}")
        cells = [cell.strip().replace("|", "\\|") for cell in row]
        lines.append(_line(cells))
        if i == 0:
            lines.append(_line(["---"] * width))
    return "\n".join(lines)
