import string

_LOWER = string.ascii_lowercase
_UPPER = string.ascii_uppercase


def rot(text, n):
    """Shift each ASCII letter by n places, wrapping around and keeping case. Other characters are unchanged."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError(f"n must be an int, got {type(n).__name__}")
    shift = n % 26
    table = str.maketrans(
        _LOWER + _UPPER,
        _LOWER[shift:] + _LOWER[:shift] + _UPPER[shift:] + _UPPER[:shift],
    )
    return text.translate(table)

