import contextlib
import io
import unittest

from textkit.cli import main
from textkit.rot import rot


def run_cli(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class RotTest(unittest.TestCase):
    def test_rot13_default_example(self):
        self.assertEqual(rot("Hello, World!", 13), "Uryyb, Jbeyq!")

    def test_wraps_around_end_of_alphabet(self):
        self.assertEqual(rot("xyz", 3), "abc")
        self.assertEqual(rot("XYZ", 3), "ABC")

    def test_keeps_case(self):
        self.assertEqual(rot("aBcD", 1), "bCdE")

    def test_leaves_other_characters(self):
        self.assertEqual(rot("1 2-3_!?\n\té", 5), "1 2-3_!?\n\té")

    def test_negative_n(self):
        self.assertEqual(rot("abc", -1), "zab")

    def test_large_n_wraps_modulo_26(self):
        self.assertEqual(rot("abc", 27), "bcd")
        self.assertEqual(rot("abc", 26), "abc")
        self.assertEqual(rot("abc", -53), "bcd" if False else rot("abc", -1))

    def test_zero_is_identity(self):
        self.assertEqual(rot("Hello", 0), "Hello")

    def test_rot13_is_its_own_inverse(self):
        self.assertEqual(rot(rot("Round Trip", 13), 13), "Round Trip")

    def test_empty_string(self):
        self.assertEqual(rot("", 13), "")

    def test_float_raises(self):
        with self.assertRaises(ValueError):
            rot("abc", 1.5)
        with self.assertRaises(ValueError):
            rot("abc", 1.0)

    def test_string_raises(self):
        with self.assertRaises(ValueError):
            rot("abc", "1")

    def test_bool_raises(self):
        with self.assertRaises(ValueError):
            rot("abc", True)
        with self.assertRaises(ValueError):
            rot("abc", False)


class RotCommandTest(unittest.TestCase):
    def test_default_is_rot13(self):
        self.assertEqual(
            run_cli("rot", "Hello, World!"),
            (0, "Uryyb, Jbeyq!\n", ""),
        )

    def test_explicit_n(self):
        self.assertEqual(run_cli("rot", "abc", "--n", "1"), (0, "bcd\n", ""))

    def test_negative_n(self):
        self.assertEqual(run_cli("rot", "abc", "--n", "-1"), (0, "zab\n", ""))

    def test_non_integer_n_is_an_error(self):
        code, out, err = run_cli("rot", "abc", "--n", "1.5")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertIn("error:", err)

    def test_non_numeric_n_is_an_error(self):
        code, out, err = run_cli("rot", "abc", "--n", "x")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertIn("error:", err)


if __name__ == "__main__":
    unittest.main()

